package com.concertstage.stage;
import java.util.*;import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.context.*;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.*;
/** Continuous stair assemblies with shared rails, grounded feet and conserved module counts. */
public final class StageFlights{
 private StageFlights(){}private static String key(int n){return String.format(Locale.ROOT,"connected_stairs_%02d",n);}
 private static Map<BlockPos,BlockState> oldCells(Level l,BlockPos p,BlockState s){Map<BlockPos,BlockState> out=new LinkedHashMap<>();if(!(s.getBlock()instanceof StageEquipmentBlock b)||!b.spec.kind.equals("stairs"))return out;BlockPos main=b.mainPos(s,p);int t=StageSpec.turns(s.getValue(StageEquipmentBlock.FACING));for(int i=0;i<b.spec.count();i++){BlockPos c=main.offset(b.spec.offset(i,t));if(StageStructure.matches(b,s,l.getBlockState(c),i)){if(!StageModules.entries(l,c).isEmpty())return Map.of();out.put(c,l.getBlockState(c));}}return out;}
 public static InteractionResult place(UseOnContext ctx,StageEquipmentBlock item){Level l=ctx.getLevel();String refund=item.spec.id+"=1";int module=StagePose.steps(item.spec.walk);if(module==0)return StageModules.fail(ctx,"stairs_incompatible");StageModules.Piece old=StageModules.nearest(l,ctx.getClickedPos(),ctx.getClickLocation(),"flight");BlockState clicked=l.getBlockState(ctx.getClickedPos());Map<BlockPos,BlockState> removed=Map.of();double x,y,z,angle;int steps,cost=1;
 if(old!=null){steps=StagePose.steps(old.spec().walk);double[] end=StagePose.point(new double[]{.5,old.spec().walk,old.spec().run},old.x(),old.y(),old.z(),old.entry().degrees());double dx=ctx.getClickLocation().x-end[0],dz=ctx.getClickLocation().z-end[2];if(dx*dx+dz*dz>.55*.55||ctx.getClickLocation().y<end[1]-.25)return StageModules.fail(ctx,"stairs_click_upper_end");if(platformAtEnd(l,end,old.entry().degrees()))return StageModules.fail(ctx,"stairs_already_reaches_deck");steps+=module;x=old.x();y=old.y();z=old.z();angle=old.entry().degrees();Map<String,Integer> counts=StagePose.refunds(old.entry().refund());counts.merge(item.spec.id,1,Integer::sum);refund=StagePose.refundString(counts);}
 else if(clicked.getBlock()instanceof StageEquipmentBlock b&&b.spec.kind.equals("stairs")){removed=oldCells(l,ctx.getClickedPos(),clicked);if(removed.isEmpty())return StageModules.fail(ctx,"space_blocked");int t=StageSpec.turns(clicked.getValue(StageEquipmentBlock.FACING));BlockPos main=b.mainPos(clicked,ctx.getClickedPos());double[] zero=StagePose.rotate(-.5,0,-.5,t*90.);x=main.getX()+.5+zero[0];y=main.getY();z=main.getZ()+.5+zero[2];angle=t*90.;double[] end=StagePose.point(new double[]{.5,b.spec.walk,b.spec.walk/.2*.3},x,y,z,angle);double dx=ctx.getClickLocation().x-end[0],dz=ctx.getClickLocation().z-end[2];if(dx*dx+dz*dz>.55*.55||ctx.getClickLocation().y<end[1]-.25)return StageModules.fail(ctx,"stairs_click_upper_end");steps=StagePose.steps(b.spec.walk)+module;Map<String,Integer> counts=new LinkedHashMap<>();counts.put(b.spec.id,1);counts.merge(item.spec.id,1,Integer::sum);refund=StagePose.refundString(counts);}
 else{StageSurfaces.Surface surface=StageSurfaces.at(l,ctx.getClickedPos());if(surface!=null){double[] hit=surface.local(ctx.getClickLocation());int side=0;double best=hit[2];double[] distances={hit[2],surface.width()-hit[0],surface.depth()-hit[2],hit[0]};for(int i=1;i<4;i++)if(distances[i]<best){best=distances[i];side=i;}double length=side%2==0?surface.width():surface.depth();if(length<1)return StageModules.fail(ctx,"stairs_incompatible");double along=Math.max(.5,Math.min(length-.5,Math.floor(side%2==0?hit[0]:hit[2])+.5));double[] edge=surface.point(side==1?surface.width():side==3?0:along,side==0?0:side==2?surface.depth():along);angle=(surface.turn()+side)*90.;if(!StageSurfaces.clearLanding(l,edge,angle))return StageModules.fail(ctx,"stairs_landing_blocked");double[] origin=null;steps=0;for(int n=1;n<=40;n++){double floor=surface.y()-n*.2;double[] c=StagePose.stairOrigin(edge[0],edge[2],floor,n,angle);if(StageSurfaces.supported(l,StageSpec.get(key(n)),c[0],c[1],c[2],angle)){origin=c;steps=n;break;}}if(origin==null)return StageModules.fail(ctx,"stairs_no_ground");x=origin[0];y=origin[1];z=origin[2];cost=(steps+module-1)/module;refund=item.spec.id+"="+cost;}
 else{BlockPlaceContext c=new BlockPlaceContext(ctx);BlockPos p=c.getClickedPos();angle=StageSpec.turns(c.getHorizontalDirection().getOpposite())*90.;double[] zero=StagePose.rotate(-.5,0,-.5,angle);x=p.getX()+.5+zero[0];y=p.getY();z=p.getZ()+.5+zero[2];steps=module;}}
 if(old!=null||!removed.isEmpty())steps=fit(l,x,y,z,angle,steps,module);if(steps<1||steps>40)return StageModules.fail(ctx,"stairs_too_high");if(ctx.getPlayer()!=null&&!ctx.getPlayer().getAbilities().instabuild&&ctx.getItemInHand().getCount()<cost)return StageModules.fail(ctx,"stairs_more_modules");StageSpec flight=StageSpec.get(key(steps));if(!StageSurfaces.supported(l,flight,x,y,z,angle))return StageModules.fail(ctx,"stairs_no_ground");if(!StageModules.place(ctx,flight,x,y,z,angle,refund,"ground",old,removed))return StageModules.fail(ctx,"space_blocked");if(!l.isClientSide&&(ctx.getPlayer()==null||!ctx.getPlayer().getAbilities().instabuild))ctx.getItemInHand().shrink(cost);return InteractionResult.sidedSuccess(l.isClientSide);}
 private static int fit(Level l,double x,double y,double z,double angle,int planned,int module){for(int n=Math.max(1,planned-module+1);n<=Math.min(40,planned);n++){double[] end=StagePose.point(new double[]{.5,n*.2,n*.3},x,y,z,angle),dir=StagePose.rotate(0,0,.02,angle);var s=StageSurfaces.at(l,BlockPos.containing(end[0]+dir[0],end[1]-.02,end[2]+dir[2]));if(s==null||Math.abs(s.y()-end[1])>.003)continue;double[] at=s.local(new Vec3(end[0],end[1],end[2])),d=StagePose.rotate(0,0,1,angle-s.turn()*90.);double gap=d[2]>.99?at[2]:d[2]<-.99?s.depth()-at[2]:d[0]>.99?at[0]:s.width()-at[0];if(Math.abs(gap)<.003&&StageSurfaces.clearLanding(l,end,angle))return n;}return planned;}
 private static boolean platformAtEnd(Level l,double[] end,double a){double[] d=StagePose.rotate(0,0,.08,a);var s=StageSurfaces.at(l,BlockPos.containing(end[0]+d[0],end[1]-.03,end[2]+d[2]));return s!=null&&Math.abs(s.y()-end[1])<.003;}
 public static InteractionResult pop(Level l,StageModules.Piece old,Player player,BlockHitResult hit){Map<String,Integer> counts=StagePose.refunds(old.entry().refund());if(counts.isEmpty())return InteractionResult.PASS;String last=null;int cap=0;for(var e:counts.entrySet()){StageSpec s=StageSpec.find(e.getKey());if(s==null||!s.kind.equals("stairs"))return InteractionResult.FAIL;cap+=StagePose.steps(s.walk)*e.getValue();last=e.getKey();}int n=StagePose.steps(old.spec().walk),kit=StagePose.steps(StageSpec.get(last).walk),next=n-Math.max(1,kit-(cap-n));if(l.isClientSide)return InteractionResult.SUCCESS;if(next<=0)StageModules.remove(l,old,null,false);else{counts.compute(last,(k,v)->v-1);UseOnContext c=new UseOnContext(player,InteractionHand.MAIN_HAND,hit);if(!StageModules.place(c,StageSpec.get(key(next)),old.x(),old.y(),old.z(),old.entry().degrees(),StagePose.refundString(counts),"ground",old,Map.of()))return InteractionResult.FAIL;}if(!player.getAbilities().instabuild)StageModules.refund(l,old.cell(),last+"=1",player);return InteractionResult.CONSUME;}
}
